{"policy":"permit (
    principal is User,
    action in [Action::"approveInvoice", Action::"issuePayment"],
    resource
)
when {
    principal.roles.contains(Role::"approver")
};

permit (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    principal.roles.contains(Role::"financeManager") &&
    context.emergencyDeclared
};

forbid (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    (principal.roles.contains(Role::"approver") ||
     principal.roles.contains(Role::"financeManager")) &&
    context.currentTime < resource.submittedAt
};

forbid (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    !context.emergencyDeclared &&
    resource.invoice has approver &&
    resource.invoice.approver == principal
};"}
